async ({ pr: { inspect }, gh: { api }, shell: { exec } }) => {
  const [p, rel, wf] = await Promise.allSettled([
    inspect({ number: 397, repo: "cv/pit" }),
    api("repos/cv/pit/releases?per_page=3"),
    exec("git fetch -q origin main && git show origin/main:.github/workflows/pi-assistant.yml | grep -n 'extensions:'; git log --oneline -5 origin/main; git status --short"),
  ]);
  const r: any = rel.status === "fulfilled" ? rel.value : rel.reason;
  const rels = (() => { try { const v = typeof r.stdout === "string" ? JSON.parse(r.stdout) : r; return (Array.isArray(v) ? v : v.data ?? []).map((x: any) => [x.tag_name, x.published_at]); } catch { return String(r).slice(0, 300); } })();
  const pv: any = p.status === "fulfilled" ? p.value : String(p.reason);
  return { pr: { state: pv.state, merged: pv.mergedAt ?? pv.merged, title: pv.title, mergeCommit: pv.mergeCommit }, rels, wf: wf.status === "fulfilled" ? wf.value.stdout : String(wf.reason) };
